export const taskStatuses = ["todo", "in progress", "done"] as const;

export type TaskStatus = (typeof taskStatuses)[number];

export class Task {
  public constructor(
    public readonly id: string,
    public readonly projectId: string,
    public readonly title: string,
    public readonly description: string,
    public readonly dueDate: Date | undefined,
    public readonly assigneeId: string | undefined,
    private currentStatus: TaskStatus = "todo",
  ) {}

  public get status(): TaskStatus {
    return this.currentStatus;
  }

  public markDone(): void {
    if (this.currentStatus === "done") {
      throw new TaskAlreadyDoneError(this.id);
    }
    this.currentStatus = "done";
  }
}

export class TaskAlreadyDoneError extends Error {
  public constructor(taskId: string) {
    super(`Task ${taskId} is already done`);
    this.name = "TaskAlreadyDoneError";
  }
}

